public class SecureServer {
    // Define a whitelist of allowed classes to prevent unexpected object creation
    private static final List<String> ALLOWED_CLASSES = Arrays.asList("java.lang.String", "java.util.ArrayList");

    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = new ServerSocket(8080);
        System.out.println("Secure server listening on port 8080...");

        while (true) {
            try (Socket socket = serverSocket.accept();
                 // Use a custom ObjectInputStream that implements class filtering
                 ValidatingObjectInputStream in = new ValidatingObjectInputStream(socket.getInputStream())) {

                Object obj = in.readObject();
                System.out.println("Received safe object: " + obj.toString());
            } catch (Exception e) {
                System.err.println("Blocked unauthorized deserialization attempt: " + e.getMessage());
            }
        }
    }

    // Custom implementation to restrict which classes can be deserialized
    static class ValidatingObjectInputStream extends ObjectInputStream {
        public ValidatingObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Check if the incoming class is in our whitelist
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
-            }
            return super.resolveClass(desc);
        }
    }
}
